#![cfg(feature = "native-cog")]

/// Use the controlled synthetic fixture generated by bench/native_cog_checks.py.
/// This checks the older convenience API as well as acquisition::prepare: it
/// must never return a successful receipt after a callback mutates a local COG.
#[test]
#[ignore = "requires TILE_RIPPER_NATIVE_REQUEST from the native COG fault harness"]
fn convenience_execute_validates_local_source_after_delivery() {
    use tile_ripper::{cog::LayoutCache, execute, Request, Source};
    let path = std::env::var("TILE_RIPPER_NATIVE_REQUEST").unwrap();
    let request: Request = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
    let Source::Assets { assets } = &request.source else {
        panic!("direct fixture required")
    };
    let source = &assets[0].locator;
    let original = std::fs::read(source).unwrap();
    let mut delivered = false;
    let result = execute(&request, &mut LayoutCache::default(), |_| {
        if !delivered {
            use std::io::Write;
            std::fs::OpenOptions::new()
                .append(true)
                .open(source)?
                .write_all(&[0])?;
            delivered = true;
        }
        Ok(())
    });
    std::fs::write(source, original).unwrap();
    assert!(delivered);
    let error = result.unwrap_err().to_string();
    assert!(error.contains("changed"), "{error}");
}
